 // OMEGA-BLOCK-START
 // Computes C = A * B. C is NOT zeroed by the caller. Any number of threads may be
 // used (std::thread is available); n is any size from 1 to 2048.
+#include <thread>
+
+constexpr int TILE = 64;
+
+static void matmul_tile(int n, const float* A, const float* B, float* C,
+                        int i0, int i1, int j0, int j1, int k0, int k1) {
+    for (int i = i0; i < i1; ++i) {
+        for (int k = k0; k < k1; ++k) {
+            float aik = A[i * n + k];
+            for (int j = j0; j < j1; ++j) {
+                C[i * n + j] += aik * B[k * n + j];
+            }
+        }
+    }
+}
+
 extern "C" void matmul(int n, const float* A, const float* B, float* C) {
-    for (int i = 0; i < n; ++i)
-        for (int j = 0; j < n; ++j) {
-            float s = 0.0f;
-            for (int k = 0; k < n; ++k) s += A[i * n + k] * B[k * n + j];
-            C[i * n + j] = s;
-        }
+    // Zero C first
+    int total = n * n;
+    for (int i = 0; i < total; ++i) C[i] = 0.0f;
+
+    const int num_threads = std::thread::hardware_concurrency();
+    std::vector<std::thread> threads;
+    threads.reserve(num_threads);
+
+    int rows_per_thread = (n + num_threads - 1) / num_threads;
+
+    for (int t = 0; t < num_threads; ++t) {
+        int i_start = t * rows_per_thread;
+        int i_end = std::min(i_start + rows_per_thread, n);
+        if (i_start >= i_end) break;
+
+        threads.emplace_back([=]() {
+            for (int jj = 0; jj < n; jj += TILE) {
+                int j_end = std::min(jj + TILE, n);
+                for (int kk = 0; kk < n; kk += TILE) {
+                    int k_end = std::min(kk + TILE, n);
+                    matmul_tile(n, A, B, C, i_start, i_end, jj, j_end, kk, k_end);
+                }
+            }
+        });
+    }
+
+    for (auto& th : threads) th.join();
 }
